#!/bin/sh\n# entrypoint.sh – prints a random quote\n# If QUOTE_INDEX env var is set, use that line (0‑based) for deterministic output (useful for tests)\n\nFILE="quotes.txt"\n\n# Read all lines into an array\ni=0\nwhile IFS= read -r line; do\n  quotes[$i]="$line"\n  i=$((i + 1))\n done < "$FILE"\n\ncount=$i\n\n# Determine index\nif [ -n "$QUOTE_INDEX" ]; then\n  idx=$QUOTE_INDEX\nelse\n  # $RANDOM is not available in /bin/sh, use awk with srand\n  idx=$(awk -v max=$count 'BEGIN{srand(); print int(rand()*max)}')\nfi\n\n# Guard against out‑of‑range\nif [ "$idx" -ge "$count" ]; then\n  idx=0\nfi\n\necho "${quotes[$idx]}"
